pub fn run<I>(args: I) -> ExitCode
where
    I: IntoIterator<Item = OsString>,
{
    let args = args.into_iter().collect::<Vec<_>>();
    if let Some(path) = default_format_path(&args) {
        return run_format(
            false,
            false,
            false,
            false,
            None,
            None,
            MarkdownWrap::Column(72),
            false,
            None,
            false,
            false,
            80,
            72,
            2,
            false,
            false,
            vec![path],
        );
    }
    match root_help_requested(&args) {
        Ok(Some(help_is_long)) => {
            let mut command = Args::command();
            let result = if help_is_long {
                command.print_long_help()
            } else {
                command.print_help()
            };
            if let Err(err) = result {
                eprintln!("error: failed to print help: {err}");
                return ExitCode::from(1);
            }
            println!();
            return ExitCode::SUCCESS;
        }
        Ok(None) => {}
        Err(arg) => {
            let mut command = Args::command();
            let err = command.error(
                ErrorKind::UnknownArgument,
                format!("unexpected argument '{}' found", arg.to_string_lossy()),
            );
            let _ = err.print();
            return ExitCode::from(2);
        }
    }

    let matches = match Args::command().try_get_matches_from(args) {
        Ok(matches) => matches,
        Err(err) => {
            let code = if matches!(
                err.kind(),
                ErrorKind::DisplayHelp | ErrorKind::DisplayVersion
            ) {
                0
            } else {
                2
            };
            let _ = err.print();
            return ExitCode::from(code);
        }
    };
    let wrap_from_cli = matches
        .subcommand_matches("format")
        .is_some_and(|matches| matches.value_source("wrap") == Some(ValueSource::CommandLine));
    let args = match Args::from_arg_matches(&matches) {
        Ok(args) => args,
        Err(err) => {
            let _ = err.print();
            return ExitCode::from(2);
        }
    };

    match args.command {
        Command::Format {
            check,
            diff,
            diagnostics,
            verify,
            stdin_file_path,
            config,
            wrap,
            table_widths,
            canonical,
            preserve_footnotes,
            line_width,
            prose_width,
            indent_width,
            compact,
            skip_embedded_formatters,
            paths,
        } => run_format(
            check,
            diff,
            diagnostics,
            verify,
            stdin_file_path,
            config,
            wrap,
            wrap_from_cli,
            table_widths,
            canonical,
            preserve_footnotes,
            line_width,
            prose_width,
"}}

